$ErrorActionPreference = 'Stop'
$project = (Get-Location).Path
$patchDir = Split-Path -Parent $MyInvocation.MyCommand.Path
$sqlSource = Join-Path $patchDir 'supabase_095_local_delivery_import_preferred.sql'

if (!(Test-Path $sqlSource)) {
  throw 'Patch163 SQL file is missing. Re-extract the ZIP before running.'
}

$excelPath = Join-Path $project 'lib/services/excel_import_service.dart'
$benefitPath = Join-Path $project 'lib/services/customer_benefit_service.dart'
if (!(Test-Path $excelPath)) { throw "Missing file: $excelPath" }
if (!(Test-Path $benefitPath)) { throw "Missing file: $benefitPath" }

$utf8 = New-Object System.Text.UTF8Encoding($false)
function Decode-Utf8Base64([string]$value) {
  return [System.Text.Encoding]::UTF8.GetString([System.Convert]::FromBase64String($value))
}
function Save-Utf8([string]$path, [string]$text) {
  [System.IO.File]::WriteAllText($path, $text, $utf8)
}

$excel = [System.IO.File]::ReadAllText($excelPath)

# 1) Add style metadata class once.
if (!$excel.Contains('class _DeliveryRowStyle {')) {
  $anchor = 'class ExcelImportService {'
  if (!$excel.Contains($anchor)) { throw 'Patch163 preflight failed: ExcelImportService anchor not found.' }
  $insert = Decode-Utf8Base64 ''
  $excel = $excel.Replace($anchor, $insert + $anchor)
}

# 2) Call local-delivery importer after route-specific discount import.
if (!$excel.Contains('await _importLocalDeliveryProfiles(bytes, workbook, routeKey: routeKey);')) {
  $anchor = '        await _importCustomerDiscountRules(workbook, routeKey: routeKey);'
  if (!$excel.Contains($anchor)) { throw 'Patch163 preflight failed: discount import call anchor not found.' }
  $replacement = $anchor + [Environment]::NewLine +
    '    await _importLocalDeliveryProfiles(bytes, workbook, routeKey: routeKey);'
  $excel = $excel.Replace($anchor, $replacement)
}

# 3) Insert local-delivery parser/importer once.
if (!$excel.Contains('Future<int> _importLocalDeliveryProfiles(')) {
  $anchor = '  Future<({int applied, int waitingForPhone})> _importCustomerDiscountRules('
  if (!$excel.Contains($anchor)) { throw 'Patch163 preflight failed: discount method anchor not found.' }
  $insert = Decode-Utf8Base64 ''
  $excel = $excel.Replace($anchor, $insert + $anchor)
}

Save-Utf8 $excelPath $excel

# 4) Prefer yellow-highlighted E/F profile in app statement matching.
$benefit = [System.IO.File]::ReadAllText($benefitPath)
if (!$benefit.Contains(".order('preferred', ascending: false)")) {
  $start = $benefit.IndexOf(".from('local_delivery_profiles')")
  if ($start -lt 0) {
    throw 'Patch163 preflight failed: local_delivery_profiles query not found.'
  }
  $limitAnchor = "        .limit(500);"
  $limit = $benefit.IndexOf($limitAnchor, $start)
  if ($limit -lt 0) {
    throw 'Patch163 preflight failed: local delivery limit anchor not found.'
  }
  $nl = if ($benefit.Contains("`r`n")) { "`r`n" } else { "`n" }
  $ordering = "        .order('preferred', ascending: false)" + $nl +
              "        .order('source_no')" + $nl
  $benefit = $benefit.Insert($limit, $ordering)
  Save-Utf8 $benefitPath $benefit
}

Copy-Item $sqlSource (Join-Path $project 'supabase/supabase_095_local_delivery_import_preferred.sql') -Force

Write-Host ''
Write-Host 'Patch163 applied successfully.'
Write-Host 'Next: run supabase/supabase_095_local_delivery_import_preferred.sql in Supabase SQL Editor.'
Write-Host 'Then run: flutter analyze'
